"""HTTP fetch implementation for the fixed local diagnostic manifest."""

import json
import urllib.request
import urllib.parse
from pathlib import Path


def _load_manifest():
    return set(json.loads(Path("diagnostics.json").read_text()))


def _is_allowed(url, allowed):
    """Check that a URL (including redirect targets) resolves to an allowed destination."""
    return url in allowed


def fetch(url: str) -> str:
    """Fetch a URL from the local diagnostic manifest.

    Only URLs listed in diagnostics.json are accepted. HTTP GET is used,
    redirects are followed (only to other allowed URLs), and the complete
    UTF-8 response text is returned.
    """
    allowed = _load_manifest()

    if url not in allowed:
        raise ValueError(f"URL not in manifest: {url}")

    class _SafeRedirectHandler(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            if newurl not in allowed:
                raise ValueError(f"Redirect target not in manifest: {newurl}")
            return super().redirect_request(req, fp, code, msg, headers, newurl)

    opener = urllib.request.build_opener(_SafeRedirectHandler)
    req = urllib.request.Request(url, method="GET")
    with opener.open(req) as resp:
        return resp.read().decode("utf-8")
